(()=>{'use strict';
let data,govFeed,govResults={},sel=null,view='ACTIVE',govOn=false;
const $=x=>document.getElementById(x),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filtered(){let q=$('search').value.toLowerCase(),a=data.records.filter(r=>(view==='ALL'||r.status===view)&&(!q||(r.jobId+' '+r.customer+' '+r.branch).toLowerCase().includes(q)));if(sel){let i=a.findIndex(r=>r.jobId===sel);if(i>0)a.unshift(a.splice(i,1)[0])}return a}
function renderGov(r){let q=govResults[r.jobId];if(!q)return'<div class="govPanel"><b>Management check</b><p>No additional check is available for this record.</p></div>';if(q.qualifiedState==='ESTABLISHED')return'<div class="govPanel good"><b>Management check · Good to go</b><p>The records on file support the current job state.</p></div>';let msg=q.findings?.[0]||({UNPROVEN:'Something needed for this job is still missing.',CONFLICTING:'The records on this job do not match.',NEGATED:'A required condition is blocked.'}[q.qualifiedState]||'This job needs attention.');return'<div class="govPanel"><b>Management check · Needs attention</b><p>'+esc(msg)+'</p><div class="govActions"><button class="btn">Assign</button><button class="btn">Contact</button><button class="btn">Request update</button><button class="btn">Hold job</button><button class="btn">Follow up</button></div></div>'}
function render(){let a=data.records,active=a.filter(x=>x.status==='ACTIVE'),done=a.filter(x=>x.status==='COMPLETED'),scheduled=active.filter(x=>x.scheduledStart),block=active.filter(x=>x.crmBlocker);$('metrics').innerHTML=[['Completed',done.length],['Active',active.length],['Scheduled',scheduled.length],['CRM-native blockers',block.length]].map(x=>'<div class="metric"><span class="muted">'+x[0]+'</span><b>'+x[1]+'</b></div>').join('');$('cycle').textContent=data.agile.cycle.name+' · '+data.agile.cycle.nativeCompletionPercent+'% recorded complete';$('objectives').innerHTML=data.agile.cycle.objectives.map(x=>'<div class="objective">'+esc(x)+'</div>').join('');let rows=filtered();$('jobs').innerHTML=rows.map(r=>'<button class="job '+(r.jobId===sel?'active':'')+'" data-id="'+r.jobId+'"><b>'+esc(r.jobId)+'</b><br><span class="muted">'+esc(r.branch)+' · '+esc(r.stage)+'</span></button>').join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{sel=b.dataset.id;render()});let r=a.find(x=>x.jobId===sel)||rows[0];if(!r){$('detail').innerHTML='<p>No job selected.</p>';return}sel=r.jobId;$('detail').innerHTML='<div class="eyebrow">CRM job record</div><h2>'+esc(r.jobId)+'</h2><p>'+esc(r.customer)+' · '+esc(r.branch)+'</p><div class="row"><span>CRM status</span><b>'+esc(r.status)+'</b></div><div class="row"><span>Workflow stage</span><b>'+esc(r.stage.replaceAll('_',' '))+'</b></div><div class="row"><span>Owner</span><b>'+esc(r.owner)+'</b></div><div class="row"><span>Opened</span><b>'+esc(r.openedOn)+'</b></div>'+(r.completedOn?'<div class="row"><span>Completed</span><b>'+esc(r.completedOn)+'</b></div>':'')+(r.scheduledStart?'<div class="row"><span>Scheduled start</span><b>'+esc(r.scheduledStart)+'</b></div>':'')+'<div class="row"><span>CRM blocker</span><b>'+(r.crmBlocker?esc(r.crmBlocker):'None recorded')+'</b></div><h3>Activity history</h3>'+r.activities.map(x=>'<div class="row"><span>'+esc(x.at)+' · '+esc(x.type)+'</span><b>'+esc(x.value)+'</b></div>').join('')+'<h3>Documents known to CRM</h3>'+r.documents.map(x=>'<div class="row"><span>'+esc(x.type)+'</span><b>'+esc(x.state)+'</b></div>').join('')+'<p class="muted">This is ABC\'s ordinary operating record.</p>'+(govOn?renderGov(r):'')}
$('search').oninput=render;$('crmGovToggle').onclick=()=>{govOn=!govOn;$('crmGovToggle').textContent='Governance: '+(govOn?'ON':'OFF');render()};$('activeFilter').onclick=()=>{view='ACTIVE';render()};$('completedFilter').onclick=()=>{view='COMPLETED';render()};$('allFilter').onclick=()=>{view='ALL';render()};
Promise.all([fetch('./crm-data-v1.json?v=20260930-crm-repair-r1',{cache:'no-store'}).then(r=>r.json()),fetch('./governance-feed-v1.json?v=20260930-crm-repair-r1',{cache:'no-store'}).then(r=>r.json())]).then(([x,g])=>{data=x;govFeed=g;govResults=Object.fromEntries(g.jobs.map(j=>[j.jobId,GovernanceAdapter.qualifyJob(j)]));let p=new URLSearchParams(location.search).get('job');sel=p&&data.records.some(r=>r.jobId===p)?p:data.records.find(r=>r.status==='ACTIVE')?.jobId;if(p){let r=data.records.find(x=>x.jobId===p);view=r?.status||'ACTIVE'}render()}).catch(e=>{console.error(e);$('detail').innerHTML='<p>CRM data failed to load.</p>'});
})();